/* eslint-disable no-unused-vars */
import React, { useEffect, useRef, useState } from 'react';
import './App.css';
import {Stages} from "./Stages";

export function Main() {
    const [selectedAnswer, setSelectedAnswer] = useState(null);
    const [radioSymbol, setradioSymbol] = useState("◇");
    const videoRef = useRef(null);
    let stageCounter = 1;
    useEffect(() => {
        if (videoRef.current) {
            const video = videoRef.current;
            video.play();
            setTimeout(() => {
                video.classList.add('remove');
            }, 2000);
        }
    }, []);

    const handleAnswerClick = (event) => {
        const selectedDiv = event.currentTarget;

        const answerDivs = document.querySelectorAll('.answer');
        answerDivs.forEach(div => {
            div.classList.remove('selected');
        });

        selectedDiv.classList.add('selected');
        

        const radioButton = selectedDiv.querySelector('input[type="radio"]');
        if (radioButton) {
            radioButton.checked = true;
            setSelectedAnswer(radioButton.id);
            setradioSymbol("◈");
        }
    };

    return (
    <div className="bkgr" id="bkgr3">
        <video className="video" ref={videoRef} id="open_curt" autoPlay muted>
            <source src="/Img/open_curt.webm" type="video/webm" />
        </video>
        <Stages />
        <form className="main_game" id="game_continue">
            <div className="question"></div>
            <div className="answer_cont">
                <fieldset>
                    <div className="answer" onClick={handleAnswerClick}><span className="answer_letter">{selectedAnswer === 'Question A' ? '◈' : '◇'} a</span>
                        <input type="radio" id="Question A" name="questions"></input>
                        <label for="Question A">Question A</label>
                    </div>
                    <div className="answer" onClick={handleAnswerClick}><span className="answer_letter">{selectedAnswer === 'Question B' ? '◈' : '◇'} b</span>
                        <input type="radio" id="Question B" name="questions"></input>
                        <label for="Question B">Question B</label>
                    </div>
                    <div className="answer" onClick={handleAnswerClick}><span className="answer_letter">{selectedAnswer === 'Question C' ? '◈' : '◇'} c</span>
                        <input type="radio" id="Question C" name="questions"></input>
                        <label for="Question C">Question C</label>
                    </div>
                    <div className="answer" onClick={handleAnswerClick}><span className="answer_letter">{selectedAnswer === 'Question D' ? '◈' : '◇'} d</span>
                        <input type="radio" id="Question D" name="questions"></input>
                        <label for="Question D">Question D</label>
                    </div>
                </fieldset>
            </div>
            <div className="line2"></div>
            <div className="option_cont">
                <div className="help_cont">
                    <div className="help" id="fifty"></div>
                    <div className="help used" id="people"></div>
                    <div className="help" id="refresh"></div>
                </div>
                <input type='submit' className="check_btn" value="Submit answer"></input> 
            </div>
            <div className="line2"></div>
        </form>
        {/* <div className="main_game dissapear" id="game_end">
            <div className="line2"></div>
            <div className="next_stage_q_cont">
                <div className="next_stage_q">Do you want to advance to the next stage or take the money?</div>
                <div className="but_cont">
                    <div className="check_btn">Take money</div> 
                    <a className="anchor" href="/lvl1/<%= questions[0]._id %>">
                        <div className="check_btn">Next stage</div>
                    </a>
                </div>
            </div>
            <div className="line2"></div>
            <div className="option_cont">
                <div className="help_cont">
                    <div className="help" id="fifty"></div>
                    <div className="help" id="people"></div>
                    <div className="help" id="refresh"></div>
                </div>
                <div className="check_btn" onclick="submit()">Submit answer</div> 
            </div>
            <div className="line2"></div>
        </div> */}
    </div>
  );
}
